import {ChartCard} from '@github-ui/chart-card'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useNavigate, useParams} from '@github-ui/react-router'
import {useIsStafftools} from '@github-ui/repos-rules/use-is-stafftools'
import {useCallback, useMemo} from 'react'
import {useTimeSpan, type TimeSpan} from '../contexts/TimeSpanContext'
import type {
  dashboardRoute,
  orgDashboardRoute,
  stafftoolsDashboardRoute,
  stafftoolsOrgDashboardRoute,
} from '../routes/dashboard-route'
import type {CategoryCount} from '../types'

type DashboardRouteConfig =
  | typeof dashboardRoute
  | typeof orgDashboardRoute
  | typeof stafftoolsDashboardRoute
  | typeof stafftoolsOrgDashboardRoute

const DEFAULT_MAX_COLUMNS = 10

const TIME_SPAN_TO_PERIOD: Record<TimeSpan, string> = {
  '7 days': 'week',
  '30 days': 'month',
  '60 days': 'month',
  '90 days': 'month',
} as const

type ColumnChartByCountBaseProps = {
  routeConfig: DashboardRouteConfig
  clickableFilterName?: string
  baseFilter?: Record<string, string>
  maxColumns?: number
  seriesData: CategoryCount[]
  isClickable?: boolean
  title: string
  description: string
  xAxisTitle: string
  yAxisTitle: string
}

type ColumnChartByCountClickableProps = ColumnChartByCountBaseProps & {
  isClickable: true
  clickableFilterName: string
}
type ColumnChartByCountStaticProps = ColumnChartByCountBaseProps & {
  isClickable?: false
  clickableFilterName?: undefined
}
type ColumnChartByCountProps = ColumnChartByCountClickableProps | ColumnChartByCountStaticProps

export function ColumnChartByCount({
  routeConfig,
  clickableFilterName,
  maxColumns = DEFAULT_MAX_COLUMNS,
  seriesData,
  baseFilter,
  isClickable = false,
  title,
  description,
  xAxisTitle,
  yAxisTitle,
}: ColumnChartByCountProps) {
  const {
    data: {sourceType, filter},
  } = useRouteQuery(routeConfig, 'mainQuery')

  const navigate = useNavigate()
  const {owner, repo, org, organizationId} = useParams<{
    owner: string
    repo: string
    org: string
    organizationId: string
  }>()
  const isStafftools = useIsStafftools()
  const {timeSpan} = useTimeSpan()
  const useCreatedFilter = isFeatureEnabled('rules_insights_filter_bar_created')

  const topEntries = useMemo(() => {
    return [...seriesData].sort((a, b) => b.count - a.count).slice(0, maxColumns)
  }, [seriesData, maxColumns])

  const categories = useMemo(
    () =>
      topEntries.map(entry => {
        const hasMultipleSources = topEntries.some(e => e.name === entry.name && e.sourceType !== entry.sourceType)
        return hasMultipleSources && entry.sourceType ? `${entry.name}\n(${entry.sourceType})` : entry.name
      }),
    [topEntries],
  )
  const data = useMemo(() => topEntries.map(entry => entry.count), [topEntries])

  const orgIdentifier = org ?? organizationId
  const insightsBasePath =
    sourceType === 'repository' && owner && repo
      ? isStafftools
        ? `/stafftools/repositories/${owner}/${repo}/repository_rules/insights`
        : `/${owner}/${repo}/settings/rules/insights`
      : orgIdentifier
        ? isStafftools
          ? `/stafftools/users/${orgIdentifier}/organization_rules/insights`
          : `/organizations/${orgIdentifier}/settings/rules/insights`
        : undefined

  const handlePointClick = useCallback(
    function (event: Highcharts.PointClickEventObject) {
      if (!isClickable || !insightsBasePath) return
      const category = String(event.point.category)
      const timePeriod = TIME_SPAN_TO_PERIOD[timeSpan] ?? 'week'
      const params = new URLSearchParams(baseFilter || {})
      if (useCreatedFilter && filter.created) {
        params.set('created', filter.created)
      } else {
        params.set('time_period', timePeriod)
      }
      if (filter.evaluateStatus) params.set('evaluate_status', filter.evaluateStatus)
      if (filter.branch && filter.branch !== 'all') params.set('ref', filter.branch)
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- handled by union props on component
      params.set(clickableFilterName!, category)
      navigate(`${insightsBasePath}?${params.toString()}`)
    },
    [baseFilter, clickableFilterName, isClickable, filter, insightsBasePath, navigate, timeSpan, useCreatedFilter],
  )

  if (!seriesData) {
    return null
  }

  return (
    <ChartCard size="medium">
      <ChartCard.Title as="h2">{title}</ChartCard.Title>
      <ChartCard.Description>{description}</ChartCard.Description>
      <ChartCard.ColumnChart
        series={[
          {
            name: yAxisTitle,
            data,
            colorByPoint: false,
          },
        ]}
        options={{
          xAxis: {
            title: xAxisTitle,
            categories,
          },
          yAxis: {
            title: `Number of ${yAxisTitle.toLocaleLowerCase()}`,
          },
        }}
        overrideOptionsNotRecommended={
          isClickable && insightsBasePath
            ? {
                plotOptions: {
                  column: {
                    cursor: 'pointer',
                    point: {
                      events: {
                        click: handlePointClick,
                      },
                    },
                  },
                },
              }
            : undefined
        }
      />
    </ChartCard>
  )
}
